  "Announcements": "Annonces",
  "announcements from the last 30 days": "annonces des 30 derniers jours",
  "Answers only from what your role can see — the same data your dashboard and screens already show you. When you ask it to do something, it prepares it and nothing happens until you press Confirm.": "Répond uniquement à partir de ce que votre rôle peut voir — les mêmes données que votre tableau de bord et vos écrans vous montrent déjà. Quand vous lui demandez de faire quelque chose, il le prépare et rien ne se passe tant que vous n'appuyez pas sur Confirmer.",
  "Any app works: Google or Microsoft Authenticator, Authy, 2FAS, Aegis, Bitwarden, 1Password. Free from the Play Store or App Store.": "N'importe quelle application convient : Google ou Microsoft Authenticator, Authy, 2FAS, Aegis, Bitwarden, 1Password. Gratuite sur le Play Store ou l'App Store.",
  "Anyone with this link can view the document until {date}.": "Toute personne disposant de ce lien peut consulter le document jusqu'au {date}.",
