  "Expected at work but no clock-in and no approved leave. Today, it can simply mean they have not arrived yet.": "Attendu au travail mais sans pointage ni congé approuvé. Aujourd'hui, cela peut simplement signifier qu'il n'est pas encore arrivé.",
