  "Fills the lines below from the unit’s rent, deposit and utility terms. Everything stays editable afterwards.": "Remplit les lignes ci-dessous à partir du loyer, du dépôt de garantie et des conditions de charges du logement. Tout reste modifiable ensuite.",
