  "Generate share link": "Générer un lien de partage",
  "Generates one payslip per active employee on the chosen cycle, with days worked pulled automatically from Attendance for the period. Leave Company as \"All companies\" to run payroll company-wide as before, or pick one company to generate a run for just its employees.": "Génère un bulletin de paie par employé actif sur le cycle choisi, les jours travaillés étant repris automatiquement des pointages de la période. Laissez Société sur « Toutes les sociétés » pour lancer la paie à l'échelle du groupe comme auparavant, ou choisissez une société pour ne traiter que ses employés.",
  "Generating…": "Génération…",
  "Get an authenticator app": "Installez une application d'authentification",
  "Getting started": "Pour commencer",
  "Ghana Card / TIN / Passport": "Carte Ghana / NIF / Passeport",
  "Given out, nobody has begun yet.": "Confiée, personne n'a encore commencé.",
  "Gives every active employee a balance for each leave type for the year you pick, from their days a year. Safe to run more than once: it never changes a balance that already exists, including one you corrected.": "Donne à chaque employé actif un solde pour chaque type de congé pour l'année choisie, à partir de ses jours par an. Peut être relancé sans risque : il ne modifie jamais un solde existant, y compris un solde corrigé.",
  "Go there": "Y aller",
