  "Good evening": "Bonsoir",
  "Good morning": "Bonjour",
  "Google Drive isn't connected yet. An administrator does this once:": "Google Drive n'est pas encore connecté. Un administrateur le fait une seule fois :",
  "GOOGLE_SERVICE_ACCOUNT_JSON on the server isn't valid JSON. Paste the whole key file again, from { to }.": "GOOGLE_SERVICE_ACCOUNT_JSON sur le serveur n'est pas un JSON valide. Collez à nouveau tout le fichier de clé, de { à }.",
  "Got it, I have read this": "C'est noté, je l'ai lue",
