  "Group photo": "Photo du groupe",
  "Group posts under one goal and dates. Tag a post with its campaign when you log it.": "Regroupez les publications sous un objectif et des dates. Rattachez une publication à sa campagne en la saisissant.",
  "Grouped by the exact tax rate found on each invoice line — where two configured taxes share a rate (e.g. NHIL and GETFund both default to 2.5%), the label shows both rather than guessing which applies.": "Regroupé selon le taux de taxe exact relevé sur chaque ligne de facture — lorsque deux taxes configurées partagent un même taux (par exemple NHIL et GETFund, tous deux à 2,5 % par défaut), le libellé indique les deux plutôt que de deviner laquelle s'applique.",
