  "Handed over": "Remis",
  "Handing out a material. It comes off the quantity on the shelf and is not expected back.": "Distribuer une fourniture. Elle est déduite de la quantité en rayon et ne revient pas.",
  "Handle": "Identifiant",
  "Handle / phone": "Identifiant / téléphone",
  "Handle / URL": "Identifiant / URL",
