  "Has an expiry date": "Avec date d'expiration",
  "has it since {date}": "l'a depuis le {date}",
  "has left": "est parti",
  "has left the company": "a quitté l'entreprise",
  "Has left. Their history is kept for records; turn on \"Show terminated employees\" to see them.": "A quitté l'entreprise. Son historique est conservé ; activez « Afficher les employés licenciés » pour le voir.",
  "Has no login for the OS. They can still clock in and out at the kiosk with their PIN.": "N'a pas d'identifiant pour l'OS. Peut quand même pointer à la borne avec son code PIN.",
  "Have {firstName} look straight at the camera, then click Capture — it walks through a few head angles (straight, left, right, up, down), about 10 seconds, to build a reference that holds up at whatever angle they happen to be at the kiosk.": "Demandez à {firstName} de regarder droit vers la caméra, puis cliquez sur Capturer — la capture passe par quelques angles de tête (face, gauche, droite, haut, bas), environ 10 secondes, pour créer une référence fiable quel que soit l'angle devant la borne.",
  "Have not bought in a while: worth winning back.": "N'ont pas acheté depuis un moment : à reconquérir.",
  "held back": "mis de côté",
  "Held back": "Mis de côté",
  "Held up by something or someone else: parts, an answer, another task.": "Bloquée par quelque chose ou quelqu'un : des pièces, une réponse, une autre tâche.",
  "Here is how {scope} is doing today: who is in, what is waiting for you, and what needs attention.": "Voici comment se porte {scope} aujourd'hui : qui est là, ce qui vous attend et ce qui demande de l'attention.",
  "Hi {firstName}, this sets up face recognition for the clock-in kiosk — once done, you'll need to look at the kiosk's camera (in addition to your PIN) every time you clock in or out.": "Bonjour {firstName}, ceci configure la reconnaissance faciale pour la borne de pointage — une fois terminé, vous devrez regarder la caméra de la borne (en plus de votre code PIN) à chaque pointage d'entrée ou de sortie.",
  "Hide": "Masquer",
  "Hide details": "Masquer les détails",
  "Hide password": "Masquer le mot de passe",
  "Hide test accounts": "Masquer les comptes de test",
  "High": "Élevée",
  "high or urgent": "importantes ou urgentes",
  "High or urgent": "Importantes ou urgentes",
  "High priority": "Priorité haute",
  "High priority \"{title}\" has not been started.": "La tâche prioritaire « {title} » n'a pas commencé.",
