  "Off by {amount} — check the manual inputs below (Cash & bank is usually the figure to correct).": "Écart de {amount} — vérifiez les saisies manuelles ci-dessous (c'est généralement « Trésorerie et banque » qu'il faut corriger).",
  "Off by {amount} vs. invoices’ recorded tax totals — likely a document-level tax rate applied outside the line items.": "Écart de {amount} par rapport aux totaux de taxe enregistrés sur les factures — probablement un taux de taxe appliqué au document plutôt qu'aux lignes.",
