  "Opens on their own phone and walks them through the same camera steps — no need to hand them this device. The link only works once and expires on its own.": "S'ouvre sur leur propre téléphone et les guide à travers les mêmes étapes devant la caméra — inutile de leur tendre cet appareil. Le lien ne fonctionne qu'une fois et expire de lui-même.",
