  "Or add a new guest": "Ou ajouter un nouvel invité",
  "Or bring in a whole month at once: File → Download → Microsoft Excel (.xlsx), and upload that. Every day tab goes onto the daily stock sheet, oldest first.": "Ou importez un mois entier d'un coup : Fichier → Télécharger → Microsoft Excel (.xlsx), puis importez ce fichier. Chaque onglet de jour est ajouté à la fiche de stock journalière, du plus ancien au plus récent.",
