  "Store credentials for third-party systems here. This links them to Bamboo OS's data model (e.g. TimeStation clock events into Attendance, Square payments into Invoices) — going live with real syncing requires the backend integration itself, not just a connected key here.": "Conservez ici les identifiants des systèmes tiers. Cela les relie au modèle de données de Bamboo OS (par exemple les pointages TimeStation vers les Pointages, les paiements Square vers les Factures) — une synchronisation réellement active nécessite l'intégration côté serveur, et pas seulement une clé enregistrée ici.",
