  "Take payments against what tenants owe, raise one-off charges, and turn meter readings and shared building bills into utility invoices. Rent itself is invoiced when a booking is made. Press a number to go to it.": "Encaissez les paiements des locataires, facturez des frais ponctuels, et transformez relevés de compteur et factures communes en factures de charges. Le loyer est facturé à la réservation. Appuyez sur un chiffre pour y aller.",
